<style scoped lang="scss" src="./fundraiser-summary-banner-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import Meter from "../meter/meter";
import Button from "../button/button";
import { MeterMode } from "../meter/meter.constants";
import { differenceInCalendarDays } from "date-fns";
import { IconShape } from "../icon/icon.constants";
import { ButtonMode } from "../button/button.constants";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";

/**
 * Shows fundraiser information and controls in a thin strip
 */
@Component({
  components: {
    Icon,
    Meter,
    Button,
  },
})
export default class FundraiserSummaryBannerBlock extends Vue {
  /** Amount currently collected for the fundraiser */
  @Prop({ type: Number, default: 0 }) collected;
  /** Fundraiser collection goal */
  @Prop({ type: Number, default: 1000 }) goal;
  /** The team associated with the fundraiser */
  @Prop({ type: Number, default: 0 }) teamNumber;
  /** Individual donation value */
  @Prop({ type: Number, default: 0 }) individualNumber;
  @Prop({ type: Number, default: 0 }) donationNumber;
  /** Fundraiser deadline */
  @Prop({ type: [Date, Number, String], default: new Date() }) dueDate;
  /** When true, puts a slight drop shadow as the bottom border of this */
  @Prop({ type: Boolean, default: false }) shadow;
  /** When true, show the days left calendar */
  @Prop({ type: Boolean, default: true }) showDaysLeft;
  /** The currency type displayed to the user */
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues),
  })
  currency;
  /** Buttons to appear under the metrics in the banner */
  @Prop({ type: Array, default: () => [] }) buttons;
  /** Hides team block if the compaign doesn't allow Teams to fundraise */
  @Prop({ type: Boolean, default: true }) teamsEnabled;

  MeterMode = MeterMode;
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  iconColor = "#2356f6";

  get daysLeft() {
    let dueDate = this.dueDate;

    if (typeof dueDate === "number" || typeof dueDate === "string") {
      dueDate = new Date(this.dueDate);

      if (dueDate.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }
    }

    const diff = differenceInCalendarDays(dueDate, new Date());

    return diff < 0 ? 0 : diff;
  }

  handleClick(index) {
    /**
     * Fires when you click on a button. This fires the event with the index of
     * the button clicked which corresponds to the buttons prop.
     *
     * @event click {number}
     */
    this.$emit("click", index);
  }
}
</script>

<template>
  <div
    :class="[
      'FundraiserSummaryBannerBlock',
      { 'FundraiserSummaryBannerBlock--Shadow': this.shadow },
    ]"
  >
    <div class="FundraiserSummaryBannerBlock__Container">
      <div class="FundraiserSummaryBannerBlock__Content">
        <div class="FundraiserSummaryBannerBlock__ResponsiveLeft">
          <div class="FundraiserSummaryBannerBlock__Left">
            <div class="FundraiserSummaryBannerBlock__LeftPadLeft" />
            <Meter
              :collected="collected"
              :goal="goal"
              :mode="MeterMode.SUMMARY"
              :currency="currency"
            />
          </div>
          <div class="FundraiserSummaryBannerBlock__Middle">
            <div class="FundraiserSummaryBannerBlock__MiddlePadLeft" />
            <div v-if="showDaysLeft" class="FundraiserSummaryBannerBlock__InfoBlock">
              <div class="FundraiserSummaryBannerBlock__InfoIcon">
                <Icon
                  :shape="IconShape.CALENDAR_CHECK"
                  :size="32"
                  :color="iconColor"
                ></Icon>
              </div>
              <div class="FundraiserSummaryBannerBlock__InfoRight">
                <div class="FundraiserSummaryBannerBlock__InfoTitle">
                  Days left
                </div>
                <div class="FundraiserSummaryBannerBlock__InfoData">
                  {{ daysLeft }}
                </div>
              </div>
            </div>
            <div class="FundraiserSummaryBannerBlock__InfoBlock">
              <div class="FundraiserSummaryBannerBlock__InfoIcon">
                <Icon
                  :shape="IconShape.PIGGY_BANK"
                  :size="32"
                  :color="iconColor"
                ></Icon>
              </div>
              <div class="FundraiserSummaryBannerBlock__InfoRight">
                <div class="FundraiserSummaryBannerBlock__InfoTitle">
                  Donations
                </div>
                <div class="FundraiserSummaryBannerBlock__InfoData">
                  {{ donationNumber }}
                </div>
              </div>
            </div>
            <div v-if="teamsEnabled" class="FundraiserSummaryBannerBlock__InfoBlock">
              <div class="FundraiserSummaryBannerBlock__InfoIcon">
                <Icon
                  :shape="IconShape.TEAM"
                  :size="32"
                  :color="iconColor"
                ></Icon>
              </div>
              <div class="FundraiserSummaryBannerBlock__InfoRight">
                <div class="FundraiserSummaryBannerBlock__InfoTitle">Teams</div>
                <div class="FundraiserSummaryBannerBlock__InfoData">
                  {{ teamNumber }}
                </div>
              </div>
            </div>
            <div class="FundraiserSummaryBannerBlock__InfoBlock">
              <div class="FundraiserSummaryBannerBlock__InfoIcon">
                <Icon
                  :shape="IconShape.INDIVIDUAL"
                  :size="32"
                  :color="iconColor"
                ></Icon>
              </div>
              <div class="FundraiserSummaryBannerBlock__InfoRight">
                <div class="FundraiserSummaryBannerBlock__InfoTitle">
                  Individuals
                </div>
                <div class="FundraiserSummaryBannerBlock__InfoData">
                  {{ individualNumber }}
                </div>
              </div>
            </div>
            <div class="FundraiserSummaryBannerBlock__MiddlePadRight" />
          </div>
        </div>
        <div class="FundraiserSummaryBannerBlock__ResponsiveRight">
          <div class="FundraiserSummaryBannerBlock__Right">
            <div
              class="FundraiserSummaryBannerBlock__Button"
              v-for="(button, i) in buttons"
              :key="i"
            >
              <Button
                @click="handleClick(i)"
                :mode="button.mode"
                :label="button.label"
                :size="button.size"
                :mobileStretch="true"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
